clc;
clear all;
close all;
n= -10:1:10;
x1=1*(n==0);  
subplot(3,2,1);     % for unit impulse %[output:532ead83]
stem(n,x1); %[output:532ead83]
xlabel("Samples"); %[output:532ead83]
ylabel("Amplitude"); %[output:532ead83]
title("Unit Impulse Signal"); %[output:532ead83]

x2=1*(n>=0);
subplot(3,2,2);      % for unit step %[output:532ead83]
stem(n,x2); %[output:532ead83]
xlabel("Samples"); %[output:532ead83]
ylabel("Amplitude"); %[output:532ead83]
title("Unit Step Signal"); %[output:532ead83]

x3=n.*(n>=0);
subplot(3,2,3);      % for unit ramp %[output:532ead83]
stem(n,x3); %[output:532ead83]
xlabel("Samples"); %[output:532ead83]
ylabel("Amplitude"); %[output:532ead83]
title("Unit Ramp Signal"); %[output:532ead83]

x4=(n.^2/2).*(n>=0);
subplot(3,2,4);       % for unit parabolic %[output:532ead83]
stem(n,x4); %[output:532ead83]
xlabel("Samples"); %[output:532ead83]
ylabel("Amplitude"); %[output:532ead83]
title("Unit Parabolic Signal"); %[output:532ead83]

x5=2*exp(n).*(n>=0);
subplot(3,2,5);       % for unit expo %[output:532ead83]
stem(n,x5); %[output:532ead83]
xlabel("Samples"); %[output:532ead83]
ylabel("Amplitude"); %[output:532ead83]
title("Unit Exponential Signal"); %[output:532ead83]

x6=1*(n>=5);
subplot(3,2,6);       % for delay unit step %[output:532ead83]
stem(n,x6); %[output:532ead83]
xlabel("Samples"); %[output:532ead83]
ylabel("Amplitude"); %[output:532ead83]
title(" Delayed Unit Step Signal"); %[output:532ead83]

